from flask import Flask, request, jsonify, make_response
app = Flask(__name__)
ORDERS = {}

@app.post("/orders")
 def create_order():
    data = request.get_json(silent=True) or {}
    if "sku" not in data:
        # 400: client must fix payload. Include machine-readable code.
        return jsonify({"type": "missing-field", "field": "sku"}), 400
    key = request.headers.get("Idempotency-Key")
    if key and key in ORDERS:
        return jsonify(ORDERS[key]), 200  # replayed POST: no duplicate
    oid = f"ord_{len(ORDERS)+1}"
    ORDERS[key or oid] = {"id": oid, **data}
    resp = make_response(jsonify(ORDERS[key or oid]), 201)
    resp.headers["Location"] = f"/orders/{oid}"  # 201 must say where
    return resp

@app.get("/orders/<oid>")
 def get_order(oid):
    order = next((o for o in ORDERS.values() if o["id"] == oid), None)
    if order is None:
        return jsonify({"type": "not-found", "id": oid}), 404
    return jsonify(order), 200

@app.delete("/orders/<oid>")
 def delete_order(oid):
    target = next((k for k, o in ORDERS.items() if o["id"] == oid), None)
    if target is None:
        return "", 404  # repeatable: deleting absent resource is still 404/204
    del ORDERS[target]
    return "", 204  # success, deliberately no body

import time, requests

RETRYABLE = {502, 503, 504}
# Never blind-retry 400/401/403/404/409/422: resending changes nothing.

def get_order(url, tries=3):
    for i in range(tries):
        r = requests.get(url, timeout=5)
        if r.status_code == 200:
            return r.json()
        if r.status_code == 404:
            return None  # definitive: absent
        if r.status_code == 429 or r.status_code == 503:
            wait = int(r.headers.get("Retry-After", 2 ** i))
            time.sleep(wait)
            continue
        if r.status_code in RETRYABLE:
            time.sleep(2 ** i)
            continue
        r.raise_for_status()  # 4xx: fix request, do not loop
    raise TimeoutError("server still failing")
